<script>
const API='ajax/social_api.php',CSRF=<?= json_encode($_SESSION['social_csrf']) ?>,ME=<?= $uid ?>;let oldest=0,busy=false,editingPost=null,feedMode='public';
const peopleSearch=document.getElementById('peopleSearch'),peopleSearchResults=document.getElementById('peopleSearchResults');
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const avatarHtml=(photo,name)=>photo?`<div class="feed-avatar"><img src="${esc(photo)}" alt="Foto de perfil de ${esc(name)}"></div>`:`<div class="feed-avatar" aria-hidden="true">${esc(name?.[0]||'U')}</div>`;
async function api(action,opt={}){const url=API+'?'+new URLSearchParams({action,...(opt.query||{})}),r=await fetch(url,opt.fetch),j=await r.json().catch(()=>({ok:false,message:'Resposta inválida.'}));if(!r.ok||!j.ok)throw new Error(j.message||'Falha na operação.');return j}
function urlDaMidiaMobile(valor){
  const original=String(valor||'').trim();
  if(!original)return '';
  // A API mobile e o site web compartilham htdocs/libras/static/uploads.
  // Caminhos locais, URLs completas e links antigos do proxy apontam para o mesmo arquivo.
  let decoded=original;
  try { decoded=decodeURIComponent(original); } catch (_) {}
  let match=decoded.match(/(?:^|\/)static\/uploads\/(social\/(?:feed|communities)\/[a-f0-9]{36,40}\.(?:jpg|jpeg|png|webp|gif|mp4|webm))(?=$|[?#])/i);
  if(!match){
    match=decoded.match(/[?&]file=(social\/(?:feed|communities)\/[a-f0-9]{36,40}\.(?:jpg|jpeg|png|webp|gif|mp4|webm))(?=$|[&#])/i);
  }
  if(match)return '../static/uploads/'+match[1];
  // Preserva mídias antigas com outros formatos ou armazenamento externo.
  return original;
}
function mediaHtml(p){const primary=p.midia_url?(p.midia_tipo==='video'?`<video class="feed-media" controls preload="metadata"><source src="${esc(urlDaMidiaMobile(p.midia_url))}"></video>`:`<img class="feed-media" src="${esc(urlDaMidiaMobile(p.midia_url))}" alt="Mídia" loading="lazy">`):'';const attachments=(p.anexos||[]).filter(f=>f.caminho!==p.midia_url).map(f=>{const src=esc(urlDaMidiaMobile(f.caminho)),name=esc(f.nome_arquivo||'Anexo');return f.mime_type?.startsWith('image/')?`<img class="feed-media" src="${src}" alt="${name}" loading="lazy">`:f.mime_type?.startsWith('video/')?`<video class="feed-media" controls preload="metadata" src="${src}"></video>`:`<a href="${src}" target="_blank" rel="noopener noreferrer" download>${name}</a>`}).join('');return primary+attachments;}
function postHtml(p){const community=p.comunidade_nome?`<span class="feed-community-context"><i class="fa-solid fa-users"></i>${esc(p.comunidade_nome)}</span>`:'';return `<article class="feed-post ui-card" id="post-${p.id_post}" data-post="${p.id_post}"><header>${avatarHtml(p.foto_perfil,p.nm_usuario)}<div><a class="feed-user-link" href="perfil.php?id=${Number(p.id_usuario)}"><strong>${esc(p.nm_usuario)}</strong></a>${Number(p.is_community_user)?'<span class="community-badge"><i class="fa-solid fa-certificate"></i>Comunitário</span>':''}${community}<time>${esc(p.criado_em)}${p.editado_em?' · editado':''}</time></div></header>${p.conteudo?`<p class="feed-post__text">${esc(p.conteudo)}</p>`:''}${mediaHtml(p)}<footer><button type="button" data-like class="feed-action ${Number(p.curtiu)?'is-active':''}" aria-label="Curtir"><i class="fa-${Number(p.curtiu)?'solid':'regular'} fa-heart"></i><span>${Number(p.total_curtidas)}</span></button><button type="button" data-comments class="feed-action"><i class="fa-regular fa-comment"></i><span>${Number(p.total_comentarios)}</span></button>${Number(p.id_usuario)===ME?'<button type="button" data-edit class="feed-action"><i class="fa-regular fa-pen-to-square"></i><span>Editar</span></button>':`<button type="button" class="feed-action report-action" data-report-type="post" data-report-id="${Number(p.id_post)}" data-report-label="Publicação de ${esc(p.nm_usuario)}" data-report-source="${esc(location.pathname)}#post-${Number(p.id_post)}"><i class="fa-regular fa-flag"></i><span>Denunciar</span></button>`}<button type="button" data-share class="feed-action"><i class="fa-solid fa-arrow-up-from-bracket"></i><span>Compartilhar</span></button></footer><section class="feed-comments" hidden></section></article>`}
async function load(reset=false){if(busy)return;busy=true;loadMore.disabled=true;if(reset){oldest=0;feedList.innerHTML=''}try{const action=feedMode==='following'?'feed_unified':'feed_public',j=await api(action,{query:oldest?{before:oldest}:{}});feedList.insertAdjacentHTML('beforeend',j.posts.map(postHtml).join(''));if(!feedList.children.length){const empty=feedMode==='following'?'<div class="feed-empty ui-card"><h2>Seu feed está pronto</h2><p>Siga pessoas ou participe de comunidades para acompanhar as publicações aqui.</p></div>':'<div class="feed-empty ui-card"><h2>A conversa começa aqui</h2><p>Seja a primeira pessoa a publicar no Social.</p></div>';feedList.innerHTML=empty}if(j.posts.length){oldest=Number(j.posts.at(-1).id_post)}loadMore.hidden=!j.has_more}catch(e){feedList.innerHTML='<div class="ui-alert ui-alert--error">'+esc(e.message)+'</div>';loadMore.hidden=true}finally{busy=false;loadMore.disabled=false}}
document.querySelectorAll('[data-feed-mode]').forEach(tab=>tab.addEventListener('click',async()=>{if(feedMode===tab.dataset.feedMode)return;feedMode=tab.dataset.feedMode;document.querySelectorAll('[data-feed-mode]').forEach(item=>{const active=item===tab;item.classList.toggle('is-active',active);item.setAttribute('aria-selected',String(active))});feedTitle.textContent=feedMode==='following'?'Seguindo':'Para você';feedDescription.textContent=feedMode==='following'?'Publicações das pessoas que você segue.':'Publicações de toda a comunidade LibrasHub.';await load(true)}));
postMedia.onchange=()=>{mediaPreview.innerHTML='';const f=postMedia.files[0];if(!f)return;const url=URL.createObjectURL(f);mediaPreview.innerHTML=f.type.startsWith('video/')?`<video src="${url}" controls></video>`:`<img src="${url}" alt="Prévia da mídia">`};
postForm.onsubmit=async e=>{e.preventDefault();postStatus.textContent='Publicando...';const fd=new FormData(e.target);fd.append('csrf',CSRF);try{await api('create_public_post',{fetch:{method:'POST',body:fd}});e.target.reset();mediaPreview.innerHTML='';postStatus.textContent='Publicado.';await load(true)}catch(x){postStatus.textContent=x.message}};
function showNotice(message,title='LibrasHub'){noticeTitle.textContent=title;noticeMessage.textContent=message;noticeDialog.hidden=false}
function closeDialog(dialog){dialog.hidden=true}
document.addEventListener('click',event=>{const close=event.target.closest('[data-dialog-close]');if(close)closeDialog(close.closest('.feed-dialog'));if(event.target.classList.contains('feed-dialog'))closeDialog(event.target)});
postEditForm.onsubmit=async event=>{event.preventDefault();if(!editingPost)return;const submit=event.submitter;submit.disabled=true;postEditStatus.textContent='Salvando...';try{await api('edit_post',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:editingPost.id,text:postEditText.value})}});closeDialog(postEditDialog);editingPost=null;await load(true);showNotice('Publicação atualizada com sucesso.','Alteração salva')}catch(error){postEditStatus.textContent=error.message}finally{submit.disabled=false}};
feedList.onclick=async e=>{const post=e.target.closest('[data-post]');if(!post)return;const id=post.dataset.post,like=e.target.closest('[data-like]'),comments=e.target.closest('[data-comments]'),edit=e.target.closest('[data-edit]'),share=e.target.closest('[data-share]');try{if(like){const j=await api('toggle_like',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:id})}});like.classList.toggle('is-active',j.liked);like.querySelector('i').className=`fa-${j.liked?'solid':'regular'} fa-heart`;like.querySelector('span').textContent=j.count}if(comments){await openComments(post,id)}if(edit){editingPost={id,post};postEditText.value=post.querySelector('.feed-post__text')?.textContent||'';postEditStatus.textContent='';postEditDialog.hidden=false;setTimeout(()=>postEditText.focus(),0)}if(share){const url=location.origin+location.pathname+'#post-'+id;if(navigator.share)await navigator.share({title:'LibrasHub Social',url});else{await navigator.clipboard.writeText(url);showNotice('Link da publicação copiado.','Compartilhar')}}}catch(x){showNotice(x.message,'Não foi possível concluir')}};
function commentTree(comments,postId){const grouped=new Map();comments.forEach(comment=>{const parent=Number(comment.id_comentario_pai)||0;if(!grouped.has(parent))grouped.set(parent,[]);grouped.get(parent).push(comment)});const render=(comment,depth=0)=>{const children=grouped.get(Number(comment.id_comentario))||[],childHtml=children.map(child=>render(child,depth+1)).join('');return `<article class="feed-comment" data-comment="${Number(comment.id_comentario)}" style="--comment-depth:${Math.min(depth,6)}"><header><a class="feed-user-link" href="perfil.php?id=${Number(comment.id_usuario)}"><strong>${esc(comment.nm_usuario)}</strong></a><time>${esc(comment.criado_em)}</time></header><p>${esc(comment.conteudo)}</p><div class="comment-actions"><button type="button" data-comment-like class="${Number(comment.curtiu)?'is-active':''}"><i class="fa-${Number(comment.curtiu)?'solid':'regular'} fa-heart"></i><span>${Number(comment.total_curtidas)}</span></button><button type="button" data-comment-reply><i class="fa-solid fa-reply"></i>Responder</button>${Number(comment.id_usuario)!==ME?`<button type="button" class="report-action" data-report-type="comentario" data-report-id="${Number(comment.id_comentario)}" data-report-label="Resposta de ${esc(comment.nm_usuario)}" data-report-source="${esc(location.pathname)}#post-${Number(postId)}"><i class="fa-regular fa-flag"></i>Denunciar</button>`:''}</div><form data-reply-form hidden><input name="text" maxlength="1200" placeholder="Responder a ${esc(comment.nm_usuario)}" required><button class="ui-button" aria-label="Enviar resposta"><i class="fa-solid fa-paper-plane"></i></button></form>${children.length?`<button type="button" class="comment-children-toggle" data-comment-children aria-expanded="false"><i class="fa-solid fa-chevron-down"></i>Ver mais (${children.length} ${children.length===1?'resposta':'respostas'})</button><div class="comment-children" hidden>${childHtml}</div>`:''}</article>`};return (grouped.get(0)||[]).map(comment=>render(comment)).join('')}
async function refreshComments(post,id){const box=post.querySelector('.feed-comments'),j=await api('comments',{query:{post:id}});box.innerHTML=`<div class="comment-list">${commentTree(j.comments,id)||'<p>Nenhum comentário ainda.</p>'}</div><form data-comment-form><input name="text" maxlength="1200" placeholder="Escreva um comentário" required><button class="ui-button" aria-label="Enviar comentário"><i class="fa-solid fa-paper-plane"></i></button></form>`;box.hidden=false;box.onclick=async event=>{const toggle=event.target.closest('[data-comment-children]');if(toggle){const children=toggle.nextElementSibling,expanded=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!expanded));children.hidden=expanded;toggle.innerHTML=`<i class="fa-solid fa-chevron-${expanded?'down':'up'}"></i>${expanded?'Ver mais':'Ocultar'} (${children.children.length} ${children.children.length===1?'resposta':'respostas'})`;return}const comment=event.target.closest('[data-comment]');if(!comment)return;const reply=event.target.closest('[data-comment-reply]'),like=event.target.closest('[data-comment-like]');if(reply){const form=comment.querySelector(':scope > [data-reply-form]');form.hidden=!form.hidden;if(!form.hidden)form.elements.text.focus()}if(like){try{const result=await api('toggle_comment_like',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:id,comment:comment.dataset.comment})}});like.classList.toggle('is-active',result.liked);like.querySelector('i').className=`fa-${result.liked?'solid':'regular'} fa-heart`;like.querySelector('span').textContent=result.count}catch(error){showNotice(error.message,'Não foi possível curtir')}}};box.onsubmit=async event=>{const form=event.target.closest('[data-comment-form],[data-reply-form]');if(!form)return;event.preventDefault();const parent=form.matches('[data-reply-form]')?form.closest('[data-comment]').dataset.comment:0;const button=form.querySelector('button');button.disabled=true;try{await api('add_comment',{fetch:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,post:id,parent,text:form.elements.text.value})}});await refreshComments(post,id);post.querySelector('[data-comments] span').textContent=j.comments.length+1}catch(error){showNotice(error.message,'Não foi possível comentar')}finally{button.disabled=false}}}
async function openComments(post,id){const box=post.querySelector('.feed-comments');if(!box.hidden){box.hidden=true;return}await refreshComments(post,id)}
let peopleSearchTimer=null;
peopleSearch?.addEventListener('input',()=>{clearTimeout(peopleSearchTimer);peopleSearchTimer=setTimeout(async()=>{const query=peopleSearch.value.trim();if(query.length<2){peopleSearchResults.innerHTML='';return}peopleSearchResults.innerHTML='<p class="people-search-status">Buscando...</p>';try{const result=await api('search',{query:{q:query}});const users=result.users||[];peopleSearchResults.innerHTML=users.length?users.map(user=>`<div class="people-result-row"><a class="people-result" href="perfil.php?id=${Number(user.id_usuario)}">${avatarHtml(user.foto_perfil,user.nm_usuario)}<span><strong>${esc(user.nm_usuario)}</strong><small>@${esc(user.social_handle||('u'+user.id_usuario))}</small></span><i class="fa-solid fa-chevron-right" aria-hidden="true"></i></a>${Number(user.id_usuario)!==ME?`<button type="button" class="people-result-report report-action" data-report-type="usuario" data-report-id="${Number(user.id_usuario)}" data-report-label="Perfil de ${esc(user.nm_usuario)}" aria-label="Denunciar perfil de ${esc(user.nm_usuario)}" title="Denunciar perfil"><i class="fa-regular fa-flag" aria-hidden="true"></i></button>`:''}</div>`).join(''):'<p class="people-search-status">Nenhuma pessoa encontrada.</p>'}catch(error){peopleSearchResults.innerHTML=`<p class="people-search-status">${esc(error.message)}</p>`}},250)});
loadMore.onclick=()=>load();load();
</script><script>
const baseCommentTree=commentTree;commentTree=(comments,postId)=>{let html=baseCommentTree(comments,postId);comments.forEach(comment=>{const marker=`<article class="feed-comment" data-comment="${Number(comment.id_comentario)}"`;const start=html.indexOf(marker);if(start<0)return;const header=html.indexOf('<header>',start);if(header<0)return;const avatar=comment.foto_perfil?`<span class="comment-avatar"><img src="${esc(comment.foto_perfil)}" alt="Foto de ${esc(comment.nm_usuario)}"></span>`:`<span class="comment-avatar" aria-hidden="true">${esc((comment.nm_usuario||'U')[0])}</span>`;html=html.slice(0,header+8)+avatar+html.slice(header+8)});const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('.comment-children .report-action').forEach(button=>{button.innerHTML='<i class="fa-regular fa-flag"></i>Denunciar resposta';button.title='Denunciar esta resposta'});return template.innerHTML};
</script><script src="../static/js/report-modal.js?v=69"></script><script>window.LibrasHubReports.init({api:'ajax/social_api.php',csrf:CSRF});</script><script src="../static/js/acessibility.js?v=69" defer></script></body></html>
